<main class="content container-fluid"><div class="row g-4"><?php foreach([['roles','Roles de usuario',$roles],['subjects','Asignaturas',$subjects],['tabulator_groups','Grupos de tabuladores',$groups],['tabulator_subgroups','Subgrupos de tabuladores',$subgroups]] as [$type,$label,$items]):?><div class="col-xl-6"><section class="card panel-card h-100"><div class="card-body p-4"><div class="d-flex align-items-center justify-content-between gap-3 mb-3"><div><span class="eyebrow">CONFIGURACIÓN</span><h2 class="h4 mt-2 mb-0"><?=e($label)?></h2></div><a class="btn btn-brand" href="<?=url('/admin/catalogos/formulario?type='.$type)?>">+ Agregar</a></div><?php if(!$items):?><div class="empty-state">Sin registros.</div><?php else:?><div class="list-group list-group-flush catalog-list"><?php foreach($items as $i):?><div class="list-group-item px-0 py-3 d-flex flex-column flex-sm-row align-items-sm-center justify-content-between gap-3"><div class="d-flex align-items-center gap-2"><span class="catalog-id">#<?=$i['id']?></span><strong><?=e($i['name'])?></strong></div><div class="d-flex flex-wrap gap-2"><a class="btn btn-sm btn-outline-success" href="<?=url('/admin/catalogos/formulario?type='.$type.'&id='.$i['id'].'&mode=view')?>">Ver</a><a class="btn btn-sm btn-outline-primary" href="<?=url('/admin/catalogos/formulario?type='.$type.'&id='.$i['id'])?>">Editar</a><form method="post" action="<?=url('/admin/catalogos/eliminar')?>" onsubmit="return confirm('¿Eliminar este registro?')"><?=csrf_field()?><input type="hidden" name="type" value="<?=$type?>"><input type="hidden" name="id" value="<?=$i['id']?>"><button class="btn btn-sm btn-outline-danger">Eliminar</button></form></div></div><?php endforeach;?></div><?php endif;?></div></section></div><?php endforeach;?></div></main>
